"""Rebuild offline illustrative snapshots using main's unchanged application CSS."""
from pathlib import Path
import html, json, shutil, subprocess
ROOT=Path(__file__).resolve().parents[3]
OUT=Path(__file__).parent
for name, source in [('app.css','src/Swoovr.Web/wwwroot/app.css'),('themes.css','src/Swoovr.Web/wwwroot/themes.css'),('admin.css','src/Swoovr.Admin/wwwroot/admin.css')]:
 shutil.copyfile(ROOT/source,OUT/name)
def field(label,value='',kind='text'):
 key=label.lower().replace(' ','-').replace("'",'')
 return f'<div class="field"><label for="{key}">{label}</label><input id="{key}" type="{kind}" value="{html.escape(value)}"></div>'
def button(text,secondary=False): return f'<button type="button" class="button {"button-secondary" if secondary else ""}" data-demo>{text}</button>'
def card(title,body): return f'<section class="card account-section"><h2>{title}</h2>{body}</section>'
def check(text): return f'<label class="check"><input type="checkbox"> {text}</label>'
def link(slug,text): return f'<a class="link" href="{slug}.html">{text}</a>'
def modes(): return '<nav class="segmented">'+''.join(f'<button class="segment" aria-pressed="{str(i==0).lower()}" data-demo>{x}</button>' for i,x in enumerate(['Dating','Friends','Activities','Business']))+'</nav>'
P=[]
def page(slug,title,source,body,group='Member',note='Illustrative populated state. Layout and controls reconstructed from the referenced component; fictional data.'):
 P.append(dict(slug=slug,title=title,source=source,body=body,group=group,note=note))
base='src/Swoovr.Web.Client/'
page('welcome','Welcome','src/Swoovr.Web/Components/Pages/Home.razor','<div class="column home"><p class="eyebrow">Real people. Clear intentions.</p><h1>Your kind of connection.</h1><p>Friendship, conversation, romance, or a shared afternoon. We’re building a little more room for the way people connect.</p><a class="primary-button" href="appearance.html">Choose your appearance</a><p class="field-help">Try eight personal colour schemes, each with light and dark modes.</p>'+card('A work in progress','<p>Member experiences and sign-in are not connected. Appearance settings save on this browser; account sync is not available yet.</p>')+'</div>','Public','Source markup and copy preserved, including the development notice on main (which is older than current signed-in functionality).')
for slug,title,fields,action in [('sign-in','Welcome back.',field('Email','alex@example.invalid','email')+field('Password','','password'),'Sign in'),('register','Create your account.',field('Email','','email')+field('Password','','password')+check("I’m 18 or over"),'Create account'),('forgot','Forgot password?',field('Email','','email'),'Send reset link')]:
 page(slug,title,'containers/keycloak/themes/swoovr/login/'+{'sign-in':'login.ftl','register':'register.ftl','forgot':'login-reset-password.ftl'}[slug],f'<div class="column"><h1>{title}</h1><p class="subtitle">Sign in to dating, friendship and things to do.</p><div class="stack">{fields}{button(action)}</div><p>{link("forgot","Forgot password?")}</p><p>In development · Starting in Adelaide · Adults 18+</p></div>','Public','Auth theme reconstruction using member form CSS; no Keycloak session or provider buttons simulated.')
quotes=[('Alex','A good walk, a long lunch, and a conversation that goes somewhere.'),('Jamie','Show me your favourite bookshop and I’ll find the coffee.'),('Morgan','Looking for company on the trail less travelled.'),('Sam','New to Adelaide. Always up for a gallery afternoon.'),('Taylor','More live music, fewer nights scrolling.'),('Casey','Let’s find a new weekend ritual.')]
tiles=''.join(f'<article class="profile-tile is-quote"><span class="tile-quote-mark">“</span><div class="tile-quote-box"><p class="tile-quote">{q}</p></div><div class="tile-name"><h2><a href="person.html">{n}</a></h2></div><p class="tile-intentions">Fictional adult · sample intention</p></article>' for n,q in quotes)
page('explore','Explore',base+'Profiles/ExplorePanel.razor','<h1>Explore</h1><p class="field-help">People in Adelaide</p><p>'+link('travel','Travel')+': plan trips and see who’s visiting.</p>'+modes()+'<div class="people-grid">'+tiles+'</div>')
page('explore-empty','Explore · empty',base+'Profiles/ExplorePanel.razor','<h1>Explore</h1>'+modes()+'<p class="field-help">No one is showing in Dating yet.</p>')
page('explore-unavailable','Explore · unavailable',base+'Profiles/ExplorePanel.razor','<h1>Explore</h1>'+card('Swoovr isn’t available in your area yet.','<p>We’re expanding to new cities.</p>'+button('Tell me when it opens')+'<p>You can still plan trips to a Swoovr city.</p>'))
page('person','Member profile',base+'Profiles/PersonPanel.razor','<p class="breadcrumb">Explore / Profile</p><h1>Jamie</h1><p class="field-help">Adelaide CBD</p>'+card('About me','<p class="field-help">Friends</p><p>Show me your favourite bookshop and I’ll find the coffee.</p>')+card('Here for','<span class="chip">Sample intention</span>')+card('Connect','<p>A request goes to one mode at a time. Nothing connects until they accept.</p><h3>Friends</h3>'+button('Send request'))+card('Block',button('Block Jamie',True))+card('Report',link('report','Report Jamie')))
page('profile-edit','Your profile',base+'Profiles/ProfileEditor.razor','<h1>Your profile</h1>'+card('About you','<p>The same in every mode. Others see it only in modes you show yourself in.</p><div class="stack">'+field('Display name','Alex')+field('Area','Adelaide CBD')+field('Home city','Adelaide')+field('About me','A good walk, a long lunch, and a conversation that goes somewhere.')+button('Save')+'</div>')+'<h2>Connection modes</h2>'+''.join(card(x,check('Use '+x)+check('Show my profile in '+x)+field('About me in '+x)) for x in ['Dating','Friends','Activities','Business']))
page('matching','Who I’d like to meet',base+'Profiles/MatchingPanel.razor','<h1>Who I’d like to meet</h1>'+card('About you','<div class="stack">'+field('Gender','Not set')+field('Pronouns (optional)')+field('Orientation (optional)')+check('Show my gender and pronouns')+check('Show my orientation')+check('Show my age')+button('Save')+'</div>')+card('Filters','<div class="stack">'+field('Mode','Dating')+field('Age from','25','number')+field('Age to','45','number')+check('ID Verified people only')+'<fieldset><legend>Must have (up to 5)</legend>'+check('Any of these')+check('All of these')+'</fieldset>'+field('Visitors in Travel','Here now and arriving soon')+button('Save filters')+'</div>'))
page('connections','Connections',base+'Connections/ConnectionsPanel.razor','<h1>Connections</h1>'+card('Requests for you','<p>'+link('person','Jamie')+' · Friends</p>'+button('Accept')+button('Decline',True))+card('Requests you sent','<p>Morgan · Activities</p>'+button('Withdraw',True))+card('Connected','<p>Sam · Friends</p>'+link('chat','Open chat')+button('Disconnect',True))+card('Blocked',"<p>You haven’t blocked anyone.</p>"))
page('connections-empty','Connections · empty',base+'Connections/ConnectionsPanel.razor','<h1>Connections</h1>'+card('Requests for you','<p>No requests waiting.</p>')+card('Requests you sent','<p>Nothing waiting for an answer.</p>')+card('Connected','<p>No connections yet. A connection starts when someone accepts a request.</p>'))
page('chats','Chats',base+'Messaging/ChatsPanel.razor','<h1>Chats</h1>'+card('Jamie',link('chat','Coffee on Saturday?'))+card('Sam',link('chat','That sounds good.')))
thread='<ul class="chat-thread"><li class="chat-day">Today · fictional conversation</li><li class="bubble">Coffee on Saturday?</li><li class="bubble mine">Sounds good. Somewhere in the city?</li><li class="bubble">Let’s choose somewhere near the bookshop.</li></ul>'
page('chat','Conversation',base+'Messaging/ConversationPanel.razor','<div class="column"><header class="chat-head"><span class="avatar">J</span><div><h1 class="chat-name">Jamie</h1><p class="chat-sub">Chats</p></div></header>'+thread+'<div class="composer"><input class="composer-input" aria-label="Message" placeholder="Message">'+button('Send')+'</div>'+link('report','Report')+'</div>')
page('chat-closed','Conversation · disconnected',base+'Messaging/ConversationPanel.razor','<div class="column"><h1>Jamie</h1>'+thread+'<p class="notice">This conversation is closed. Messages are read-only.</p></div>')
page('travel','Travel',base+'Travel/TravelPanel.razor','<h1>Travel</h1>'+link('traveller-search','Traveller Search')+card('Plan a trip','<div class="stack">'+field('Destination','Adelaide')+field('Arrival','2026-11-12','date')+field('Departure','2026-11-16','date')+button('Save trip')+'</div>')+card('Your trips','<h3>Adelaide</h3><p>12–16 November 2026 · Upcoming</p>'+button('Confirm arrival',True))+card('Visitors (Adelaide)',modes()+'<p>No one is visiting in Dating yet.</p>'))
page('traveller-search','Traveller Search',base+'Travel/TravellerSearchPanel.razor','<h1>Traveller Search</h1><p class="field-help">Illustrative destination and dates.</p><div class="stack">'+field('Destination','Adelaide')+field('Arrival','2026-11-12','date')+field('Departure','2026-11-16','date')+button('Search')+'</div>'+modes()+'<div class="people-grid">'+tiles[:tiles.find('</article>')+10]+'</div>')
page('account','Me · account',base+'Account/MemberAccountPanel.razor','<h1>Hello, Alex.</h1>'+card('Your session','<dl><dt>Email</dt><dd>alex@example.invalid</dd><dt>Account</dt><dd>Fictional beta member</dd></dl>')+card('Your age',field('Date of birth','','date')+'<p class="field-help">It’s never shown; your age is, unless you hide it.</p>'+button('Save'))+card('Mobile number',link('phone','Verify mobile number'))+'<div class="card settings-list">'+''.join(f'<a href="{s}.html">{t} →</a>' for s,t in [('profile-edit','Your profile'),('matching','Who I’d like to meet'),('appearance','Appearance'),('verification','ID verification'),('notices','Notices and reports'),('data','Data and account')])+'</div>')
page('phone','Mobile number',base+'Account/PhonePanel.razor','<h1>Mobile number</h1>'+card('Mobile number','<p class="field-help">Required to complete registration. Codes are simulated for local development.</p><div class="stack">'+field('Mobile number','','tel')+button('Send code',True)+field('Code sent to masked number')+button('Confirm')+'</div>'))
page('verification','ID verification',base+'Account/VerificationPanel.razor','<h1>ID verification</h1>'+card('Your ID check','<p>Optional and free. Didit checks a government photo ID and a live selfie.</p><p class="field-help">The ID Verified badge says your ID was checked; it doesn’t say you’re safe.</p>'+button('Verify my ID')+'<p class="field-help">Gallery only: no identity verification takes place.</p>'))
page('dob-correction','Date of birth correction',base+'Account/DobCorrectionPrompt.razor',card('Your date of birth doesn’t match your ID','<p>Illustrative correction prompt.</p>'+field('Date of birth on your ID','','date')+button('Confirm')))
page('report','Report a member',base+'Moderation/ReportForm.razor','<h1>Jamie</h1>'+card('Report','<div class="stack">'+field('Reason','Choose a reason')+field('Anything else we should know (optional)')+check('Also block Jamie')+'<p class="field-help">If someone is in immediate danger, contact emergency services (000 in Australia).</p>'+button('Send report')+'</div>'))
page('notices','Notices and reports',base+'Moderation/NoticesPanel.razor','<h1>Notices and reports</h1>'+card('About your account','<p>No notices.</p>')+card('Your reports',"<p>You haven’t reported anything.</p>"))
page('data','Data and account',base+'Account/DataAndDeletionPanel.razor','<h1>Data and account</h1>'+card('Your data',button('Download my data',True))+card('Delete your account','<p class="field-help">Review retention and deletion details in the application before confirming.</p>'+check('Delete immediately')+check('I understand and want to delete my account')+button('Delete my account')))
page('restricted','Account restricted',base+'Account/MemberAccountPanel.razor','<h1>Hello, Alex.</h1>'+card('Your account is restricted','<p>Read the notice for the reason and your appeal options.</p>'+link('notices','Read the notice')))
page('appearance','Appearance','src/Swoovr.Web/Components/Pages/Appearance.razor','<h1>Appearance</h1><p>Only changes your own interface.</p><h2>Colour scheme</h2><div class="scheme-grid">'+''.join(f'<label class="scheme-choice"><input type="radio" name="scheme" value="{s}" {"checked" if s=="standard" else ""}> {n}<div class="palette-swatch swatch-{s}-light"><i></i><b></b></div></label>' for s,n in [('standard','Standard'),('lounge','Lounge'),('pride','Pride'),('trans','Trans'),('union','Union Jack'),('violet','Violet'),('coral','Coral'),('eucalyptus','Eucalyptus')])+'</div><h2>Display mode</h2><select id="display-mode" aria-label="Display mode"><option>System</option><option>Light</option><option>Dark</option></select><p class="field-help">Gallery preview only; does not save to an account.</p>')
admin='src/Swoovr.Admin/Components/Pages/'
page('admin','Moderation',admin+'Home.razor','<h1>Moderation</h1><ul class="tiles"><li><a href="queue.html"><strong>3</strong>open cases</a></li><li><a href="queue.html"><strong>1</strong>urgent awaiting acknowledgement</a></li><li><a href="appeals.html"><strong>1</strong>appeals waiting</a></li></ul><p class="help">Support sees the support queue; admins also see staff-affiliated cases. Every action is recorded with its reason.</p>','Staff')
page('queue','Moderation queue',admin+'Cases.razor','<h1>Queue</h1><nav class="filters">Open · Reviewed · Closed · All</nav><table><thead><tr><th>Priority</th><th>Member</th><th>Reports</th><th>Queue</th><th>Status</th></tr></thead><tbody><tr><td>Normal</td><td><a href="case.html">Fictional member</a></td><td>1</td><td>Support</td><td>Open</td></tr></tbody></table>','Staff')
page('case','Moderation case',admin+'Case.razor','<h1>Fictional member</h1><dl class="facts"><div><dt>Status</dt><dd>Open</dd></div><div><dt>Priority</dt><dd>Normal</dd></div><div><dt>Queue</dt><dd>Support</dd></div></dl>'+button('Start review',True)+'<h2>Reports (1)</h2><p>Illustrative report · no real member information.</p><h2>Evidence</h2><pre>No private evidence included in this gallery.</pre><h2>Action</h2><div class="stack"><label>Action <select><option>Dismiss (no action)</option><option>Warn</option><option>Restrict</option></select></label>'+field('Reason (shown to the member)')+button('Apply')+'</div>','Staff')
page('appeals','Appeals',admin+'Appeals.razor','<h1>Appeals</h1><p class="help">Decided by someone other than the original decider.</p><ul class="list"><li><strong>Restriction</strong> · fictional account<blockquote>Please review this decision. Fictional sample.</blockquote><div class="row">'+button('Uphold',True)+button('Overturn (lift)')+'</div></li></ul>','Staff')
page('accounts','Account lookup',admin+'Accounts.razor','<h1>Accounts</h1><div class="row">'+field('Exact email','alex@example.invalid','email')+button('Find')+'</div><ul class="list"><li>'+link('admin-account','members account')+' · active · created 27 Oct 2026</li></ul>','Staff')
page('admin-account','Account tools',admin+'Account.razor','<h1>Account</h1>'+card('Member account','<p>Fictional account · active</p>')+card('Location and arrival','<p>Outcomes only: Swoovr keeps no coordinates, IP addresses or places.</p>')+card('Plus for testers','<p>Complimentary: never charged.</p><div class="stack">'+field('Days','30','number')+field('Reason')+button('Grant')+'</div>'),'Staff','Representative excerpt of a long account-tools page; not every administrative operation is reproduced.')
page('dob-reviews','Date of birth reviews',admin+'DobReviews.razor','<h1>Date of birth reviews</h1><p class="help">A mismatch alone isn’t fraud.</p><ul class="list"><li>Fictional member · still different after the correction<div class="row">'+field('Reason')+button('Date of birth matches the ID')+button('Leave it unverified',True)+'</div></li></ul>','Staff')
sha=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()
style=''' .gallery-meta{padding:14px 24px;border-bottom:1px solid var(--border);background:var(--soft);font-size:12px}.gallery-meta a{margin-right:12px}.gallery-meta p{margin:8px 0 0}.gallery-index{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.gallery-index a{display:block;padding:20px;border:1px solid var(--border);border-radius:14px;text-decoration:none;background:var(--surface)}.stack{display:grid;gap:10px}.gallery-controls{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.gallery-status{min-height:24px}table{display:block;overflow:auto} .gallery-meta code{overflow-wrap:anywhere}'''
(OUT/'gallery.css').write_text(style)
script='''document.addEventListener('click',e=>{if(e.target.closest('[data-demo]'))document.querySelector('.gallery-status').textContent='Illustrative control only. No request sent and no data saved.'});document.addEventListener('submit',e=>e.preventDefault());const theme=()=>{const v=document.querySelector('#display-mode')?.value||document.querySelector('#gallery-mode')?.value||'System';document.documentElement.dataset.theme=v==='System'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):v.toLowerCase()};document.querySelector('#gallery-mode')?.addEventListener('change',theme);document.querySelector('#display-mode')?.addEventListener('change',theme);document.querySelectorAll('[name=scheme]').forEach(x=>x.addEventListener('change',()=>document.documentElement.dataset.scheme=x.value));theme();'''
(OUT/'gallery.js').write_text(script)
def document(title,body,staff=False):
 css='admin.css' if staff else 'app.css'
 return f'<!doctype html><html lang="en" data-scheme="standard" data-theme="light"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} — Swoovr UI gallery</title><link rel="stylesheet" href="themes.css"><link rel="stylesheet" href="{css}"><link rel="stylesheet" href="gallery.css"><body>{body}<script src="gallery.js"></script></body></html>'
for i,p in enumerate(P):
 nav='<header class="'+('admin-header' if p['group']=='Staff' else 'app-header')+'"><a class="wordmark" href="index.html">Swoovr</a><nav class="tab-bar">'+''.join(f'<a class="tab" href="{s}.html">{t}</a>' for s,t in ([('admin','Moderation'),('queue','Queue'),('appeals','Appeals'),('accounts','Accounts'),('dob-reviews','Date of birth')] if p['group']=='Staff' else [('explore','Explore'),('connections','Connections'),('chats','Chats'),('account','Me')]))+'</nav></header>'
 meta=f'<aside class="gallery-meta"><div class="gallery-controls"><a href="index.html">All {len(P)} screens</a><a href="{P[(i-1)%len(P)]["slug"]}.html">Previous</a><a href="{P[(i+1)%len(P)]["slug"]}.html">Next</a><label>Preview <select id="gallery-mode"><option>System</option><option>Light</option><option>Dark</option></select></label></div><p>{p["note"]}</p><p>Source: <code>{p["source"]}</code></p><div class="gallery-status" role="status" aria-live="polite">Offline gallery · fictional adults · controls are illustrative</div></aside>'
 (OUT/(p['slug']+'.html')).write_text(document(p['title'],meta+nav+'<main class="'+('admin-main' if p['group']=='Staff' else '')+'">'+p['body']+'</main>',p['group']=='Staff'))
index=f'<main><p class="eyebrow">Main branch review / 27 October 2026</p><h1>Swoovr, screen by screen.</h1><p>{len(P)} offline HTML snapshots of the public, member and staff interfaces. Open any screen, resize the browser, and switch light/dark. These are source-based reconstructions, not screenshots of authenticated sessions.</p><p><strong>CONFIRMED:</strong> Standard black and white is the default; eight schemes are personal choices. <strong>DEFAULT:</strong> fictional populated examples and static controls. <strong>OPEN:</strong> runtime and native-device visual parity.</p><p>Base main commit: <code>{sha}</code>. CSS copied unchanged from that commit. Auth screens approximate the hosted Keycloak layout; native MAUI screens are not rendered here. Planned commerce, venue, vouchers and photo-upload screens are excluded.</p>'
for group in ['Public','Member','Staff']:
 index+=f'<h2 class="section-heading">{group}</h2><div class="gallery-index">'+''.join(f'<a href="{p["slug"]}.html"><span class="eyebrow">{group}</span><h2>{p["title"]}</h2><span>View screen →</span></a>' for p in P if p['group']==group)+'</div>'
index+='</main>'
(OUT/'index.html').write_text(document('Screen index',index))
(OUT/'manifest.json').write_text(json.dumps({'base_commit':sha,'screens':[{k:v for k,v in p.items() if k!='body'} for p in P]},indent=2))
print(f'Built {len(P)} screens at {OUT}')
